/**
- Clouds are particles moving along Bezier paths
- The blur, fog, god rays, and rainbow are applied in the
  postprocessing shader
*/

const particleSystems = []
const trees = []
const numParticles = 200
let fbo
let postprocessShader

function setup() {
	createCanvas(600, 600, WEBGL)
	fbo = createFramebuffer()
	postprocessShader = createShader(vert, frag)
	particleSystems.push(
		new ParticleSystem({
			guidingCurve: createGuidingCurve(0),
			numParticles: 300,
		}),
		new ParticleSystem({
			guidingCurve: createGuidingCurve(PI * 0.9),
			numParticles: 300,
			scale: 1.5,
		}),
	)
	for (let i = 0; i < 800; i++) {
		trees.push(new Tree())
	}
}

function draw() {
	background(0)

	const eyeZ = (height/2) / tan(PI/6)
  const near = eyeZ/10
  const far = eyeZ*10
  perspective(PI/3, width/height, near, far)

	const targetDepth = 1200
  const blurIntensity = 0.015
	const fogColor = color('#50607a')
	const ambientColor = color('#60646e')
	const skyColor = color('#f5d2a4')
	const sideSkyColor = color('#282d2e')
	const treeColor = color('#282e33')
	const lightColor = color('#b8b47d')

	const t = millis()

  fbo.draw(() => {
		clear()
		push()
		ambientLight(ambientColor)
		pointLight(skyColor, 0, -2 * height, -800)
		pointLight(sideSkyColor, width, -100, -200)

		noStroke()
		fill('#b1bee0')

		translate(0, 0, -100)
		push()
		pointLight(lightColor, -width*0.1, -400, -600)
		for (const system of particleSystems) {
			system.draw(t)
		}
		pop()

		push()
		lightFalloff(1, 0, 1)
		pointLight(lightColor, -width*0.1, 0, -600)

		fill(treeColor)
		translate(0, height*0.8, -600)
		rotateX(PI / 2)
		plane(width * 16, width * 16)
		pop()

		push()
		lightFalloff(0.1, 0.001, 0)
		pointLight(lightColor, -width*0.1, 0, -600)

		fill(treeColor)
		for (const tree of trees) {
			tree.draw(t)
		}
		pop()

		pop()
	})

	clear()

  push()

  noStroke()
  rectMode(CENTER)
  shader(postprocessShader)
  _renderer.getTexture(fbo.depth).setInterpolation(
    _renderer.GL.NEAREST,
    _renderer.GL.NEAREST
  )
  postprocessShader.setUniform('uImg', fbo.color)
  postprocessShader.setUniform('uDepth', fbo.depth)
  postprocessShader.setUniform('uSize', [width, height])
  // try replacing blurIntensity with 0 to see an unblurred version
  postprocessShader.setUniform('uIntensity', blurIntensity)
  postprocessShader.setUniform('uNumSamples', 15)
  postprocessShader.setUniform('uTargetZ', targetDepth)
  postprocessShader.setUniform('uNear', near)
  postprocessShader.setUniform('uFar', far)
	postprocessShader.setUniform('uFogColor', [red(fogColor)/255, green(fogColor)/255, blue(fogColor)/255])
	postprocessShader.setUniform('uFogScale', 0.0005)
	postprocessShader.setUniform('uTime', t)


  rect(0, 0, width, -height)
  pop()
}

// === Tab: BezierPath ===
const SAMPLE_SPACING = 2

class BezierSegment {
  constructor(A, B, C, D) {
    this.A = A
    this.B = B
    this.C = C
    this.D = D
  }

  tangentAtParameter(parameter) {
    var t = Math.max(0, Math.min(1, parameter)) // clamp to [0, 1]
    const adjustedT = 1 - t
    const x =
      3 * this.D.x * Math.pow(t, 2) -
      3 * this.C.x * Math.pow(t, 2) +
      6 * this.C.x * adjustedT * t -
      6 * this.B.x * adjustedT * t +
      3 * this.B.x * Math.pow(adjustedT, 2) -
      3 * this.A.x * Math.pow(adjustedT, 2)

    const y =
      3 * this.D.y * Math.pow(t, 2) -
      3 * this.C.y * Math.pow(t, 2) +
      6 * this.C.y * adjustedT * t -
      6 * this.B.y * adjustedT * t +
      3 * this.B.y * Math.pow(adjustedT, 2) -
      3 * this.A.y * Math.pow(adjustedT, 2)

    const z =
      3 * this.D.z * Math.pow(t, 2) -
      3 * this.C.z * Math.pow(t, 2) +
      6 * this.C.z * adjustedT * t -
      6 * this.B.z * adjustedT * t +
      3 * this.B.z * Math.pow(adjustedT, 2) -
      3 * this.A.z * Math.pow(adjustedT, 2)

    return { x, y, z }
  }

  pointAtParameter(parameter) {
    var t = Math.max(0, Math.min(1, parameter)) // clamp to [0, 1]
    return {
      x:
        Math.pow(1 - t, 3) * this.A.x +
        3 * Math.pow(1 - t, 2) * t * this.B.x +
        3 * (1 - t) * Math.pow(t, 2) * this.C.x +
        Math.pow(t, 3) * this.D.x,
      y:
        Math.pow(1 - t, 3) * this.A.y +
        3 * Math.pow(1 - t, 2) * t * this.B.y +
        3 * (1 - t) * Math.pow(t, 2) * this.C.y +
        Math.pow(t, 3) * this.D.y,
      z:
        Math.pow(1 - t, 3) * this.A.z +
        3 * Math.pow(1 - t, 2) * t * this.B.z +
        3 * (1 - t) * Math.pow(t, 2) * this.C.z +
        Math.pow(t, 3) * this.D.z,
    }
  }

  getTotalLength() {
    if (this._totalLength === undefined) {
      const initialSamples = Math.max(
        10,
        Math.ceil(
          (Math.hypot(this.B.x - this.A.x, this.B.y - this.A.y, this.B.z - this.A.z) +
            Math.hypot(this.C.x - this.B.x, this.C.y - this.B.y, this.C.z - this.A.z) +
            Math.hypot(this.D.x - this.C.x, this.D.y - this.C.y, this.D.z - this.C.z)) /
            SAMPLE_SPACING
        )
      )
      const pts = times(initialSamples).map((i) =>
        this.pointAtParameter(i / (initialSamples - 1))
      )
      let total = 0
      for (let i = 1; i < pts.length; i++) {
        total += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y, pts[i].z - pts[i - 1].z)
      }
      this._totalLength = total
    }

    return this._totalLength
  }
}

class BezierPath {
  constructor(segments) {
    this.segments = segments
    this.samples = []

    const segmentLengths = segments.map((s) => s.getTotalLength())
    const segmentOffsets = [0]
    for (let i = 1; i < segmentLengths.length; i++) {
      segmentOffsets.push(segmentOffsets[i - 1] + segmentLengths[i - 1])
    }
    this._totalLength =
      segmentOffsets[segmentOffsets.length - 1] +
      segmentLengths[segmentLengths.length - 1]

    const numSamples = Math.max(
      10,
      Math.ceil(this._totalLength / SAMPLE_SPACING)
    )
    const stepSize = 1 / numSamples / 10

    const avgDist = this._totalLength / numSamples
    this.samples.push({
      dist: 0,
      pt: this.segments[0].A,
      tan: this.segments[0].tangentAtParameter(0),
      segIdx: 0,
      t: 0,
    })
    segments.forEach((seg, segIdx) => {
      const numSegSamples = Math.max(
        1,
        Math.round(numSamples * (seg.getTotalLength() / this._totalLength))
      )

      // Include one extra point at the end at t = 1
      const ts = times(numSegSamples + 1).map((i) => i / numSegSamples)
      var pts = ts.map((t) => seg.pointAtParameter(t))
      let dists
      for (let it = 0; it < 4; it++) {
        dists = times(numSegSamples).map((i) =>
          Math.hypot(pts[i + 1].x - pts[i].x, pts[i + 1].y - pts[i].y, pts[i + 1].z - pts[i].z)
        )
        const distErrors = dists.map((d) => d - avgDist)
        let offset = 0
        for (let i = 1; i < ts.length - 1; i++) {
          // Shift this t value to get closer to the target length
          offset += distErrors[i - 1]
          ts[i] -= stepSize * offset

          // Sample the point at the new t value
          pts[i] = seg.pointAtParameter(ts[i])
        }
      }

      let lastOffset = 0
      pts.slice(1).forEach((pt, i) => {
        lastOffset += dists[i]
        this.samples.push({
          dist: segmentOffsets[segIdx] + lastOffset,
          pt,
          tan: this.segments[segIdx].tangentAtParameter(ts[i + 1]),
          segIdx,
          t: ts[i + 1],
        })
      })
    })
  }

  getTotalLength() {
    return this._totalLength
  }

  findClosestSampleIdx(dist) {
    // Binary search to find the sample with the closest dist
    let lo = 0
    let hi = this.samples.length - 1

    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2)

      if (this.samples[mid].dist > dist) {
        hi = mid - 1
      } else if (this.samples[mid].dist < dist) {
        lo = mid + 1
      } else {
        return mid
      }
    }

    return Math.max(
      0,
      Math.min(this.samples.length - 1, Math.floor((lo + hi) / 2)),
    )
  }

  getPointAtLength(length, approximate) {
    if (length <= 0) return this.samples[0].pt
    if (length >= this._totalLength)
      return this.samples[this.samples.length - 1].pt

    const idxA = this.findClosestSampleIdx(length)
    const idxB =
      this.samples[idxA].dist < length
        ? Math.min(idxA + 1, this.samples.length - 1)
        : Math.max(0, idxA - 1)
    const mix =
      (length - this.samples[idxA].dist) /
      (this.samples[idxB].dist - this.samples[idxA].dist)

    if (
      approximate ||
      this.samples[idxA].segIdx !== this.samples[idxB].segIdx
    ) {
      // We have a set of evenly spaced samples that are close enough together
      // that we can probably just linearly interpolate between them without
      // too much loss of quality
      var x =
        (1 - mix) * this.samples[idxA].pt.x + mix * this.samples[idxB].pt.x
      var y =
        (1 - mix) * this.samples[idxA].pt.y + mix * this.samples[idxB].pt.y
      var z =
        (1 - mix) * this.samples[idxA].pt.z + mix * this.samples[idxB].pt.z
      return { x, y, z }
    } else {
      // Find the t value between the two samples. This is not EXACTLY the point
      // at the target distance along the path, but it's so close that it
      // is effectively the same
      const segment = this.segments[this.samples[idxA].segIdx]
      var t = (1 - mix) * this.samples[idxA].t + mix * this.samples[idxB].t
      return segment.pointAtParameter(t)
    }
  }

  getTangentAtLength(length, approximate) {
    if (length <= 0) return this.samples[0].tan
    if (length >= this._totalLength)
      return this.samples[this.samples.length - 1].tan

    var idxA = this.findClosestSampleIdx(length)
    var idxB =
      this.samples[idxA].dist < length
        ? Math.min(idxA + 1, this.samples.length - 1)
        : Math.max(0, idxA - 1)
    var mix =
      (length - this.samples[idxA].dist) /
      (this.samples[idxB].dist - this.samples[idxA].dist)

    if (
      approximate ||
      this.samples[idxA].segIdx !== this.samples[idxB].segIdx
    ) {
      // We have a set of evenly spaced samples that are close enough together
      // that we can probably just linearly interpolate between them without
      // too much loss of quality
      var x =
        (1 - mix) * this.samples[idxA].tan.x + mix * this.samples[idxB].tan.x
      var y =
        (1 - mix) * this.samples[idxA].tan.y + mix * this.samples[idxB].tan.y
      var z =
        (1 - mix) * this.samples[idxA].tan.z + mix * this.samples[idxB].tan.z
      return { x, y, z }
    } else {
      // Find the t value between the two samples. This is not EXACTLY the point
      // at the target distance along the path, but it's so close that it
      // is effectively the same
      var segment = this.segments[this.samples[idxA].segIdx]
      var t = (1 - mix) * this.samples[idxA].t + mix * this.samples[idxB].t
      return segment.tangentAtParameter(t)
    }
  }
}

function times(n) {
	const arr = new Array(n)
	for (let i = 0; i < n; i++) {
		arr[i] = i
	}
	return arr
}


const createBezierPath = (points) => {
  const segments = []
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1]
    const curr = points[i]
    segments.push(
      new BezierSegment(
        prev.pt,
        prev.right || prev.pt,
        curr.left || curr.pt,
        curr.pt,
      ),
    )
  }
  return new BezierPath(segments)
}

// === Tab: createGuidingCurve ===
function createGuidingCurve(angle) {
	const points = [
		{ pt: createVector(-width, -height / 2, 200) },
		{ pt: createVector(width * 0.3, -height / 2, 70) },
		{ pt: createVector(width * 0.8, -height / 2, -200) },
		{ pt: createVector(-width / 8, -height / 2, -700) },
		{ pt: createVector(-width / 6, height, -700) },
	]

	const rotateAbout = points[points.length-1].pt.copy()
	for (const point of points) {
		point.pt.sub(rotateAbout)
		const pt2D = createVector(point.pt.x, point.pt.z)
		pt2D.rotate(angle)
		point.pt.set(pt2D.x, point.pt.y, pt2D.y)
		point.pt.add(rotateAbout)
	}
	// Add bezier tangent control points to make it smooth
	for (let i = 1; i < points.length - 1; i++) {
		var prev = points[(i - 1 + points.length) % points.length]
		var curr = points[i]
		const next = points[(i + 1) % points.length]
		const tangent = next.pt.copy().sub(prev.pt).mult(1/8)
		curr.left = curr.pt.copy().sub(tangent)
		curr.right = curr.pt.copy().add(tangent)
	}
	return createBezierPath(points)
}

// === Tab: Particle ===
class Particle {
	constructor() {
		this.t = random()
		this.offset = createVector(
			randomGaussian(0, 200/3),
			randomGaussian(0, 100/3),
			randomGaussian(0, 50/3),
		)
		this.size = max(10, randomGaussian(20, 20/3))
		this.noiseOffset = random(1000)
		this.noiseScale = random(0.8, 1.2)
	}

	draw(guidingCurve, time) {
		push()
		const rawT = (this.t + time * 0.00001) % 1
		const fractionBeforeFall = 0.95
		const verticalCutoff = 0.65
		var t = rawT < fractionBeforeFall
			? map(rawT, 0, fractionBeforeFall, 0, verticalCutoff)
			: map(rawT, fractionBeforeFall, 1, verticalCutoff, 1)
		const position = guidingCurve.getPointAtLength(t * guidingCurve.getTotalLength())
		const rawTangent = guidingCurve.getTangentAtLength(t * guidingCurve.getTotalLength())
		var tangent = createVector(rawTangent.x, rawTangent.y, rawTangent.z).normalize()
		const bitangent = createVector(-tangent.z, -0.1, tangent.x).normalize()
		const normal = tangent.copy().cross(bitangent).normalize()

		const ox = this.offset.x + this.size * 0.5 * sin(time * 0.001 * this.noiseScale + this.noiseOffset)
		const oy = this.offset.y + this.size * 0.5 * sin(0.5 + time * 0.001 * this.noiseScale + this.noiseOffset)
		const oz = this.offset.z + this.size * 0.5 * sin(0.75 + time * 0.001 * this.noiseScale + this.noiseOffset)

		const verticality = pow(abs(tangent.y), 8)
		const size = map(t, verticalCutoff, 0.75, 3, 0.2, true) * map(t, 0, 0.05, 0, 1, true)
		const stretch = map(t, verticalCutoff+0.05, 0.75, 1, 5, true)
		//const stretch = map(pow(verticality, 2), 0, 1, 1, 8)
		const offStretch = map(verticality, 0, 1, 1, 0.3)

		translate(position.x, position.y, position.z)
		// Change of basis to point along the curve
		applyMatrix(
			bitangent.x, bitangent.y, bitangent.z, 0,
			normal.x, normal.y, normal.z, 0,
			tangent.x, tangent.y, tangent.z, 0,
			0, 0, 0, 1,
		)
		translate(ox * offStretch, oy * offStretch, oz * offStretch)
		scale(size, size, max(size, stretch))
		sphere(this.size, 8, 5)
		pop()
	}
}

// === Tab: ParticleSystem ===
class ParticleSystem {
	constructor({ guidingCurve, numParticles, scale = 1 }) {
		this.guidingCurve = guidingCurve
		this.scale = scale
		this.particles = []
		for (let i = 0; i < numParticles; i++) {
			this.particles.push(new Particle())
		}
	}

	draw(time) {
		push()
		scale(this.scale)
		for (const particle of this.particles) {
			particle.draw(this.guidingCurve, time)
		}
		pop()
	}
}

// === Tab: Tree ===
class Tree {
	constructor() {
		this.x = random(-1, 1) * width * 2
		this.y = random(-2, 0) * height
		this.size = randomGaussian(1, 0.1) * map(noise(this.x*0.1, this.y*0.1), 0, 2, 1, 15, true)
		this.noiseOffset = random(5) + noise(this.x*0.2, this.y*0.2, 1000)
	}

	draw(t) {
		push()
		translate(this.x, height*0.6, this.y)
		scale(this.size, -this.size, this.size)
		rotateZ(map(sin(t*0.003 + this.noiseOffset), -1, 1, 0, 1) * PI*0.02)
		translate(0, 15, 0)
		cone(5, 30, 10, 3)
		pop()
	}
}

// === Tab: postprocessing ===
const vert = `precision highp float;
	attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aTexCoord;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec2 vVertTexCoord;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertTexCoord = aTexCoord;
  }
`
const frag = `precision highp float;
  varying highp vec2 vVertTexCoord;

  uniform sampler2D uImg;
  uniform sampler2D uDepth;
  uniform vec2 uSize;
  uniform float uIntensity;
  uniform int uNumSamples;
  uniform float uTargetZ;
  uniform float uNear;
  uniform float uFar;
	uniform vec3 uFogColor;
	uniform float uFogScale;
	uniform float uTime;

  const int MAX_NUM_SAMPLES = 50;
	var int NUM_RAYS = 3;

  float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
  }

  float depthToZ(float depth) {
    float depthNormalized = 2.0 * depth - 1.0;
    return 2.0 * uNear * uFar / (uFar + uNear - depthNormalized * (uFar - uNear));
  }

  float calcBlur(float z, float pixelScale) {
    return clamp(abs(z - uTargetZ), 0.0, 0.5*pixelScale);
  }

	vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
  }

	vec4 adjustColor(float z, vec2 uv, vec4 color) {
		vec4 base = mix(color, vec4(uFogColor, 1.), 1. - exp(-uFogScale*z));
		float rayOffsets[NUM_RAYS];
		float rayWidths[NUM_RAYS];
		float raySlopes[NUM_RAYS];
		rayOffsets[0] = 0.21 + 0.03*sin(uTime * 0.001);
		rayOffsets[1] = 0.1 + 0.01*sin(uTime * 0.0008) + 0.005*sin(uTime * 0.0016 + 0.2);
		rayOffsets[2] = 0.25 + 0.01*sin(uTime * 0.0006 + 0.1) + 0.005*sin(uTime * 0.0012 + 0.3);
		rayWidths[0] = 0.1;
		rayWidths[1] = 0.15;
		rayWidths[2] = 0.15;
		raySlopes[0] = 0.23;
		raySlopes[1] = 0.35;
		raySlopes[2] = 0.2;
		if (z > 1000. && uv.y > 0.18) {
			for (int i = 0; i < NUM_RAYS; i++) {
				if (uv.x > uv.y*(raySlopes[i]) + rayOffsets[i] && uv.x < uv.y*(raySlopes[i]-rayWidths[i]) + rayOffsets[i] + rayWidths[i]) {
					base += vec4(0.05, 0.05, 0.05, 0.) * smoothstep(0.18, 0.19, uv.y);
				}
			}

			vec2 local = uv - vec2(0.35, 0.2);
			float distToCenter = length(local);
			float minR = 0.3;
			float maxR = 0.35;
			if (distToCenter > minR && distToCenter < maxR) {
				float hue = (distToCenter - minR) / (maxR - minR);
				float angle = atan(local.y, local.x);
				base += vec4(0.15*hsv2rgb(vec3(hue, 1., 1.)), 0.)
					* smoothstep(0.18, 0.19, uv.y) // Fade in bottom
					* smoothstep(0.1, 1.5, angle) // Fade in right
					* smoothstep(-2.75, -0.5, -angle); // Fade in left
				//base += 0.25*vec4(1., 0.5, 0.5, 0.) * smoothstep(0.18, 0.19, uv.y);
			}
		}
		return base;
	}

  void main() {
    float pixelScale = max(uSize.x, uSize.y);
    float total = 1.0;
    float origZ = depthToZ(texture2D(uDepth, vVertTexCoord).x);
    vec4 color = adjustColor(origZ, vVertTexCoord, texture2D(uImg, vVertTexCoord));
    float blurAmt = calcBlur(origZ, pixelScale);
    for (int i = 0; i < MAX_NUM_SAMPLES; i++) {
      if (i >= uNumSamples) break;
      float t = (float(i + 1) / float(uNumSamples));
      float angle = (t*4.0) * ${2 * Math.PI};
      float radius = 1.0 - (t*t*t); // Sample more on the outer edge
      angle += 1.*rand(gl_FragCoord.xy);
      vec2 offset = (vec2(cos(angle),sin(angle)) * radius * uIntensity * blurAmt)/pixelScale;
      float z = depthToZ(texture2D(uDepth, vVertTexCoord + offset).x);
      float sampleBlur = calcBlur(z, pixelScale);

      float weight = float((z >= origZ) || (sampleBlur >= blurAmt*radius + 5.));
			vec4 sample = adjustColor(z, vVertTexCoord + offset, texture2D(uImg, vVertTexCoord + offset));
      color += weight * sample;
      total += weight;
    }
    color /= total;
		gl_FragColor = color;
  }
  `

